#!/usr/bin/env python3
"""Resolve the package version from env vars, a CI-generated file, or git tags."""

import os
import subprocess
from pathlib import Path

# Used when no other version source is available.
FALLBACK_VERSION = "1.0.0"


def get_git_version():
    """Derive a PEP 440-style version from `git describe`.

    Returns:
        The version string (e.g. "0.29.2", "0.29.2.dev3+dirty"), or None if git
        is unavailable or there is no tag (git then yields a bare commit hash).
    """
    try:
        package_dir = Path(__file__).parent.parent  # parent of twitter_blocker/

        result = subprocess.run(
            ["git", "describe", "--tags", "--always", "--dirty"],
            cwd=package_dir,
            capture_output=True,
            text=True,
            check=True,
        )

        version = result.stdout.strip()

        if version.startswith("v"):
            version = version[1:]

        # no tag: "<hash>" or "<hash>-dirty" has no dot in its first segment, so treat as unknown
        if "." not in version.split("-")[0]:
            return None

        # Untagged-commit form: <tag>-<commits since tag>-g<hash>[-dirty], e.g. 0.29.2-3-g1234567-dirty
        if "-" in version:
            parts = version.split("-")
            base_version = parts[0]

            commits_since = parts[1] if len(parts) > 1 else "0"

            is_dirty = version.endswith("-dirty")
            if is_dirty:
                # strip "-dirty" so the commit count is parts[1]
                parts = version.replace("-dirty", "").split("-")
                commits_since = parts[1] if len(parts) > 1 else "0"

            if commits_since != "0":
                version = f"{base_version}.dev{commits_since}"
            else:
                version = base_version

            if is_dirty:
                version += "+dirty"

        return version

    except (subprocess.CalledProcessError, FileNotFoundError):
        return None


def get_app_version_file():
    """Read the version from the `.app-version` file in the repository root.

    Returns:
        The stripped file contents, or None if the file is missing, empty or unreadable.
    """
    try:
        package_dir = Path(__file__).parent.parent
        app_version_file = package_dir / ".app-version"
        
        if app_version_file.exists():
            version = app_version_file.read_text().strip()
            if version:
                return version
    except Exception:
        pass
    return None


def get_package_version():
    """Return the package version.

    Sources, in priority order:
    1. env TWITTER_BLOCKER_VERSION
    2. env APPLICATION_VERSION (Docker/CI)
    3. `.app-version` file generated by CI
    4. git tags
    5. FALLBACK_VERSION
    """
    env_version = os.environ.get("TWITTER_BLOCKER_VERSION")
    if env_version:
        return env_version

    app_env_version = os.environ.get("APPLICATION_VERSION")
    if app_env_version:
        return app_env_version

    app_version = get_app_version_file()
    if app_version:
        return app_version

    git_version = get_git_version()
    if git_version:
        return git_version

    return FALLBACK_VERSION


__version__ = get_package_version()